import Script from 'next/script';
import { redirect } from 'next/navigation';
import { createServerSupabase } from '@/lib/supabase/server';

/**
 * سجل الحضور الذكي (تجاري) — مستضاف على المنصة، بيانات كل معلمة في السحابة.
 * البوابة: تسجيل دخول + اشتراك حضور سارٍ (أو أدمِن). سجلان مجاناً + شراء إضافي.
 * التخزين + حدّ الجهازين عبر /api/attendance، وقراءة الكشوف عبر /api/ocr.
 */
export const dynamic = 'force-dynamic';

const ATT_CSS = ":root{\n  --sage:#7A9E7E; --sage-dark:#5F8163; --sage-light:#EAF1EB;\n  --gold:#C9A84C; --gold-light:#F6EFDC;\n  --ivory:#FAF8F3; --ink:#2E3830; --muted:#7C877E;\n  --present:#3E9B5F; --present-bg:#E7F5EC;\n  --absent:#D64545; --absent-bg:#FBE9E9;\n  --late:#D9A821; --late-bg:#FBF3DC;\n  --excused-out:#E07B39; --excused-out-bg:#FCEEE2;\n  --excused-abs:#8E5EA8; --excused-abs-bg:#F1E9F7;\n  --card:#FFFFFF; --radius:16px;\n  --shadow:0 2px 10px rgba(46,56,48,.07);\n}\n*{margin:0;padding:0;box-sizing:border-box;font-family:'Tajawal',sans-serif;-webkit-tap-highlight-color:transparent}\nbody{background:var(--ivory);color:var(--ink);min-height:100vh}\nbutton{cursor:pointer;border:none;background:none;font-family:inherit}\ninput,select,textarea{font-family:inherit;font-size:1rem}\n\n/* ===== Header ===== */\n.topbar{background:linear-gradient(135deg,var(--sage-dark),var(--sage));color:#fff;padding:14px 20px;display:flex;align-items:center;justify-content:space-between;position:sticky;top:0;z-index:50;box-shadow:var(--shadow)}\n.brand{display:flex;align-items:center;gap:10px}\n.brand .leaf{width:38px;height:38px;background:#fff;border-radius:12px;display:flex;align-items:center;justify-content:center;font-size:1.3rem}\n.brand h1{font-size:1.15rem;font-weight:800}\n.brand small{display:block;font-size:.72rem;opacity:.85;font-weight:400}\n.topbar .actions{display:flex;gap:8px}\n.icon-btn{background:rgba(255,255,255,.15);color:#fff;border-radius:10px;padding:8px 12px;font-size:.85rem;font-weight:700;transition:.2s}\n.icon-btn:hover{background:rgba(255,255,255,.28)}\n\n.container{max-width:1080px;margin:0 auto;padding:22px 16px 80px}\n\n/* ===== Home: class cards ===== */\n.home-head{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:18px}\n.home-head h2{font-size:1.3rem;font-weight:800;color:var(--sage-dark)}\n.home-date{color:var(--muted);font-size:.9rem;font-weight:500}\n.btn{border-radius:12px;padding:11px 20px;font-weight:800;font-size:.95rem;transition:.2s;display:inline-flex;align-items:center;gap:7px}\n.btn-gold{background:var(--gold);color:#fff}\n.btn-gold:hover{filter:brightness(1.06)}\n.btn-sage{background:var(--sage);color:#fff}\n.btn-sage:hover{background:var(--sage-dark)}\n.btn-ghost{background:#fff;color:var(--sage-dark);border:1.5px solid var(--sage)}\n.btn-ghost:hover{background:var(--sage-light)}\n.btn-danger{background:#fff;color:var(--absent);border:1.5px solid var(--absent)}\n.btn-sm{padding:7px 13px;font-size:.83rem;border-radius:10px}\n\n.class-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:14px}\n.class-card{background:var(--card);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow);cursor:pointer;transition:.2s;border:2px solid transparent;position:relative;overflow:hidden}\n.class-card:hover{transform:translateY(-3px);border-color:var(--sage)}\n.class-card .ribbon{position:absolute;top:0;right:0;left:0;height:5px}\n.class-card h3{font-size:1.1rem;font-weight:800;margin-bottom:4px}\n.class-card .meta{color:var(--muted);font-size:.82rem;margin-bottom:12px}\n.status-pill{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 12px;font-size:.8rem;font-weight:700}\n.pill-done{background:var(--present-bg);color:var(--present)}\n.pill-none{background:var(--absent-bg);color:var(--absent)}\n.pill-part{background:var(--late-bg);color:#A87F14}\n.class-card .mini-stats{display:flex;gap:10px;margin-top:10px;font-size:.78rem;color:var(--muted)}\n.empty-state{text-align:center;padding:60px 20px;color:var(--muted)}\n.empty-state .big{font-size:3rem;margin-bottom:10px}\n.empty-state p{margin-bottom:18px;font-size:1rem}\n\n/* ===== Modal ===== */\n.overlay{position:fixed;inset:0;background:rgba(30,40,32,.45);display:none;align-items:flex-start;justify-content:center;z-index:100;padding:24px 14px;overflow-y:auto}\n.overlay.open{display:flex}\n.modal{background:#fff;border-radius:20px;max-width:560px;width:100%;padding:26px;box-shadow:0 20px 60px rgba(0,0,0,.2);animation:pop .25s}\n@keyframes pop{from{transform:scale(.95);opacity:0}to{transform:scale(1);opacity:1}}\n.modal h3{color:var(--sage-dark);font-size:1.2rem;font-weight:800;margin-bottom:16px;display:flex;align-items:center;gap:8px}\n.field{margin-bottom:14px}\n.field label{display:block;font-weight:700;font-size:.88rem;margin-bottom:6px;color:var(--ink)}\n.field input,.field select,.field textarea{width:100%;border:1.5px solid #DDE4DE;border-radius:11px;padding:10px 13px;background:var(--ivory);outline:none;transition:.2s}\n.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--sage);background:#fff}\n.field textarea{min-height:130px;resize:vertical;line-height:1.9}\n.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n.modal .foot{display:flex;gap:10px;justify-content:flex-start;margin-top:20px;flex-wrap:wrap}\n.hint{font-size:.78rem;color:var(--muted);margin-top:5px;line-height:1.7}\n.seg{display:flex;background:var(--ivory);border-radius:11px;padding:4px;gap:4px}\n.seg button{flex:1;border-radius:8px;padding:8px;font-weight:700;font-size:.85rem;color:var(--muted);transition:.2s}\n.seg button.on{background:var(--sage);color:#fff}\n\n/* ===== Attendance view ===== */\n.att-head{background:var(--card);border-radius:var(--radius);padding:16px;box-shadow:var(--shadow);margin-bottom:16px}\n.att-head .row1{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px}\n.att-head h2{font-size:1.15rem;font-weight:800;color:var(--sage-dark)}\n.att-head .sub{color:var(--muted);font-size:.82rem;margin-top:2px}\n.date-nav{display:flex;align-items:center;gap:6px;background:var(--ivory);border-radius:11px;padding:5px 8px}\n.date-nav button{font-size:1.1rem;color:var(--sage-dark);padding:4px 8px;border-radius:8px;font-weight:800}\n.date-nav button:hover{background:var(--sage-light)}\n.date-nav input{border:none;background:none;font-weight:700;color:var(--ink);outline:none;text-align:center}\n.quickbar{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}\n.chip{border-radius:999px;padding:8px 15px;font-weight:700;font-size:.82rem;background:var(--ivory);color:var(--ink);border:1.5px solid #E2E8E3;transition:.2s}\n.chip:hover{border-color:var(--sage)}\n.chip.on{background:var(--sage);color:#fff;border-color:var(--sage)}\n.search-box{flex:1;min-width:170px;display:flex;align-items:center;gap:8px;background:var(--ivory);border:1.5px solid #E2E8E3;border-radius:999px;padding:7px 14px}\n.search-box input{border:none;background:none;outline:none;width:100%;font-size:.88rem}\n\n.summary-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(95px,1fr));gap:10px;margin-bottom:16px}\n.sum-card{background:var(--card);border-radius:13px;padding:11px 8px;text-align:center;box-shadow:var(--shadow);border-top:4px solid var(--sage)}\n.sum-card .num{font-size:1.35rem;font-weight:800}\n.sum-card .lbl{font-size:.74rem;color:var(--muted);font-weight:700}\n\n.students-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(215px,1fr));gap:11px}\n.st-card{background:var(--card);border-radius:14px;padding:13px 14px;box-shadow:var(--shadow);cursor:pointer;user-select:none;display:flex;align-items:center;gap:11px;border:2px solid transparent;transition:transform .12s, border-color .15s, background .15s;position:relative}\n.st-card:active{transform:scale(.97)}\n.st-num{min-width:30px;height:30px;border-radius:9px;background:var(--sage-light);color:var(--sage-dark);font-weight:800;font-size:.85rem;display:flex;align-items:center;justify-content:center}\n.st-name{flex:1;font-weight:700;font-size:.93rem;line-height:1.4}\n.st-status{font-size:1.25rem;line-height:1}\n.st-card[data-s=\"present\"]{border-color:#CDE8D6;background:linear-gradient(0deg,var(--present-bg),#fff)}\n.st-card[data-s=\"absent\"]{border-color:var(--absent);background:linear-gradient(0deg,var(--absent-bg),#fff)}\n.st-card[data-s=\"late\"]{border-color:var(--late);background:linear-gradient(0deg,var(--late-bg),#fff)}\n.st-card[data-s=\"excused_out\"]{border-color:var(--excused-out);background:linear-gradient(0deg,var(--excused-out-bg),#fff)}\n.st-card[data-s=\"excused_abs\"]{border-color:var(--excused-abs);background:linear-gradient(0deg,var(--excused-abs-bg),#fff)}\n.st-card .info-btn{position:absolute;top:6px;left:6px;font-size:.75rem;color:var(--muted);background:var(--ivory);border-radius:7px;padding:2px 7px;opacity:.75}\n.st-card .info-btn:hover{color:var(--sage-dark);opacity:1}\n\n.legend{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0;font-size:.8rem;color:var(--muted);align-items:center}\n.legend span{display:flex;align-items:center;gap:5px;font-weight:700}\n.dot{width:11px;height:11px;border-radius:50%}\n\n/* ===== Tabs ===== */\n.tabs{display:flex;gap:6px;background:var(--card);border-radius:14px;padding:6px;box-shadow:var(--shadow);margin-bottom:16px;overflow-x:auto}\n.tabs button{flex:1;min-width:90px;border-radius:10px;padding:10px 6px;font-weight:800;font-size:.86rem;color:var(--muted);transition:.2s;white-space:nowrap}\n.tabs button.on{background:var(--sage);color:#fff}\n\n/* ===== Stats ===== */\n.panel{background:var(--card);border-radius:var(--radius);padding:18px;box-shadow:var(--shadow);margin-bottom:16px}\n.panel h3{color:var(--sage-dark);font-weight:800;font-size:1.05rem;margin-bottom:14px;display:flex;align-items:center;gap:8px}\n.bars{display:flex;align-items:flex-end;gap:8px;height:150px;padding-top:10px}\n.bar-col{flex:1;display:flex;flex-direction:column;align-items:center;gap:5px;height:100%;justify-content:flex-end}\n.bar{width:100%;max-width:42px;background:linear-gradient(180deg,var(--sage),var(--sage-dark));border-radius:7px 7px 3px 3px;min-height:3px;transition:height .4s;position:relative}\n.bar .v{position:absolute;top:-20px;right:50%;transform:translateX(50%);font-size:.68rem;font-weight:800;color:var(--sage-dark)}\n.bar-lbl{font-size:.68rem;color:var(--muted);font-weight:700;text-align:center}\n\n/* ===== Calendar ===== */\n.cal-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}\n.cal-head b{font-size:1rem;color:var(--sage-dark)}\n.cal-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}\n.cal-grid .dow{text-align:center;font-size:.7rem;font-weight:800;color:var(--muted);padding:5px 0}\n.cal-day{aspect-ratio:1;border-radius:10px;background:var(--ivory);display:flex;flex-direction:column;align-items:center;justify-content:center;font-size:.8rem;font-weight:700;cursor:pointer;transition:.15s;border:1.5px solid transparent;gap:2px}\n.cal-day:hover{border-color:var(--sage)}\n.cal-day.has{background:var(--sage-light)}\n.cal-day.today{border-color:var(--gold)}\n.cal-day .mini{display:flex;gap:2px}\n.cal-day .mini i{width:5px;height:5px;border-radius:50%;display:block}\n.cal-day.blank{background:transparent;cursor:default;border:none}\n\n/* ===== Report table ===== */\n.tbl-wrap{overflow-x:auto}\ntable.rep{width:100%;border-collapse:collapse;font-size:.86rem}\ntable.rep th{background:var(--sage);color:#fff;padding:9px 8px;font-weight:800;font-size:.8rem}\ntable.rep td{padding:8px;border-bottom:1px solid #EDF1ED;text-align:center;font-weight:500}\ntable.rep td.nm{text-align:right;font-weight:700}\ntable.rep tr:hover td{background:var(--sage-light)}\ntable.rep th:first-child{border-radius:0 10px 10px 0}\ntable.rep th:last-child{border-radius:10px 0 0 10px}\n.rate-pill{border-radius:999px;padding:3px 10px;font-weight:800;font-size:.78rem}\n\n/* ===== Student profile ===== */\n.profile-top{display:flex;align-items:center;gap:16px;flex-wrap:wrap}\n.avatar{width:66px;height:66px;border-radius:50%;background:linear-gradient(135deg,var(--sage),var(--gold));color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.5rem;font-weight:800}\n.ring-wrap{position:relative;width:110px;height:110px;margin:0 auto}\n.ring-wrap svg{transform:rotate(-90deg)}\n.ring-wrap .pct{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:800;font-size:1.3rem;color:var(--sage-dark)}\n.ring-wrap .pct small{font-size:.65rem;color:var(--muted);font-weight:700}\n.log-list{display:flex;flex-direction:column;gap:7px;max-height:280px;overflow-y:auto}\n.log-item{display:flex;justify-content:space-between;align-items:center;background:var(--ivory);border-radius:10px;padding:9px 13px;font-size:.85rem;font-weight:600}\n\n/* ===== Toast ===== */\n.toast{position:fixed;bottom:22px;right:50%;transform:translateX(50%);background:var(--ink);color:#fff;border-radius:999px;padding:11px 22px;font-weight:700;font-size:.88rem;box-shadow:0 8px 24px rgba(0,0,0,.25);opacity:0;pointer-events:none;transition:.3s;z-index:200}\n.toast.show{opacity:1;bottom:32px}\n\n.footer-note{text-align:center;color:var(--muted);font-size:.75rem;margin-top:34px;line-height:1.8}\n\n/* ===== Print ===== */\n@media print{\n  body{background:#fff}\n  .topbar,.quickbar,.tabs,.att-head .row1 .noprint,.legend,.footer-note,.btn,.date-nav button{display:none!important}\n  .container{max-width:100%;padding:0}\n  .panel,.att-head{box-shadow:none;border:1px solid #ccc}\n  .print-header{display:block!important;text-align:center;margin-bottom:14px;border-bottom:2px solid var(--sage);padding-bottom:10px}\n  table.rep th{background:#e8efe9!important;color:#000!important;-webkit-print-color-adjust:exact}\n}\n.print-header{display:none}\n@media(max-width:560px){\n  .students-grid{grid-template-columns:repeat(auto-fill,minmax(160px,1fr))}\n  .grid-2{grid-template-columns:1fr}\n  .brand h1{font-size:1rem}\n}";
const ATT_BODY = "<header class=\"topbar\">\n  <div class=\"brand\">\n    <div class=\"leaf\">🌿</div>\n    <div><h1>سجل الحضور الذكي<small>غراس المعلم</small></h1></div>\n  </div>\n  <div class=\"actions\">\n    <a href=\"/\" class=\"icon-btn\" style=\"text-decoration:none;background:rgba(255,255,255,.22)\">← رجوع لمنصة غراس</a>\n    <span id=\"syncBadge\" style=\"align-self:center;font-size:.72rem;font-weight:700;color:rgba(255,255,255,.75);margin-inline-end:4px\">☁️ سحابي</span>\n    <button class=\"icon-btn\" id=\"homeBtn\" onclick=\"goHome()\" style=\"display:none\">🏠 الرئيسية</button>\n    <button class=\"icon-btn\" onclick=\"backupData()\">💾 نسخة احتياطية</button>\n    <button class=\"icon-btn\" onclick=\"document.getElementById('restoreFile').click()\">📂 استعادة</button>\n    <input type=\"file\" id=\"restoreFile\" accept=\".json\" hidden onchange=\"restoreData(this)\">\n  </div>\n</header>\n\n<div class=\"container\" id=\"app\"></div>\n\n<!-- Class creation modal -->\n<div class=\"overlay\" id=\"classModal\">\n  <div class=\"modal\">\n    <h3>📘 <span id=\"classModalTitle\">إنشاء فصل جديد</span></h3>\n    <div class=\"grid-2\">\n      <div class=\"field\"><label>المرحلة الدراسية</label>\n        <select id=\"cStage\"><option>الابتدائية</option><option>المتوسطة</option><option>الثانوية</option></select></div>\n      <div class=\"field\"><label>الصف</label>\n        <select id=\"cGrade\"><option>الأول</option><option>الثاني</option><option>الثالث</option><option>الرابع</option><option selected>الخامس</option><option>السادس</option><option>السابع</option><option>الثامن</option><option>التاسع</option><option>العاشر</option><option>الحادي عشر</option><option>الثاني عشر</option></select></div>\n      <div class=\"field\"><label>الشعبة</label><input id=\"cSection\" placeholder=\"مثال: ١\"></div>\n      <div class=\"field\"><label>المادة</label><input id=\"cSubject\" placeholder=\"التربية الإسلامية\" value=\"التربية الإسلامية\"></div>\n      <div class=\"field\"><label>العام الدراسي</label><input id=\"cYear\" value=\"2026/2027\"></div>\n      <div class=\"field\"><label>نوع الفصل</label>\n        <div class=\"seg\" id=\"cGenderSeg\">\n          <button class=\"on\" data-g=\"girls\" onclick=\"segPick(this)\">🎀 بنات</button>\n          <button data-g=\"boys\" onclick=\"segPick(this)\">🧢 بنين</button>\n        </div></div>\n      <div class=\"field\"><label>اسم المدرسة <span style=\"color:var(--muted);font-weight:500\">(اختياري)</span></label><input id=\"cSchool\" placeholder=\"مثال: مدرسة مشرف الابتدائية بنات\"></div>\n      <div class=\"field\"><label style=\"display:flex;align-items:center;gap:10px;justify-content:space-between\">\n        <span>اسم <span id=\"teacherWord\">المعلمة</span> <span style=\"color:var(--muted);font-weight:500\">(اختياري)</span></span>\n        <span class=\"seg\" id=\"cTeacherSeg\" style=\"padding:3px;font-size:.78rem\">\n          <button class=\"on\" data-t=\"f\" onclick=\"teacherPick(this)\" type=\"button\" style=\"padding:4px 12px\">👩‍🏫 معلمة</button>\n          <button data-t=\"m\" onclick=\"teacherPick(this)\" type=\"button\" style=\"padding:4px 12px\">👨‍🏫 معلم</button>\n        </span></label>\n        <input id=\"cTeacher\" placeholder=\"أ. ...\"></div>\n    </div>\n    <div class=\"field\">\n      <label id=\"namesLabel\">أسماء الطالبات (اسم في كل سطر أو مفصولة بفواصل)</label>\n      <textarea id=\"cNames\" placeholder=\"الصقي الأسماء هنا...&#10;فاطمة أحمد العلي&#10;نورة خالد المطيري&#10;...\"></textarea>\n      <div class=\"hint\">💡 يمكنج النسخ مباشرة من كشف المدرسة أو من ملف Excel (نسخ العمود ولصقه هنا). سيتم الترتيب حسب ترتيب اللصق.</div>\n      <div style=\"margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center\">\n        <button class=\"btn btn-ghost btn-sm\" id=\"ocrBtn\" onclick=\"document.getElementById('ocrCam').click()\">📸 تصوير الكشف</button>\n        <button class=\"btn btn-ghost btn-sm\" onclick=\"document.getElementById('ocrLib').click()\">🖼️ من مكتبة الصور</button>\n        <span class=\"hint\" id=\"ocrStatus\" style=\"margin:0\"></span>\n        <input type=\"file\" id=\"ocrCam\" accept=\"image/*\" capture=\"environment\" hidden onchange=\"ocrExtract(this)\">\n        <input type=\"file\" id=\"ocrLib\" accept=\"image/*\" hidden onchange=\"ocrExtract(this)\">\n      </div>\n    </div>\n    <div class=\"foot\">\n      <button class=\"btn btn-sage\" onclick=\"saveClass()\">✅ حفظ الفصل</button>\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('classModal')\">إلغاء</button>\n    </div>\n  </div>\n</div>\n\n<!-- Student profile modal -->\n<div class=\"overlay\" id=\"studentModal\">\n  <div class=\"modal\" id=\"studentModalBody\"></div>\n</div>\n\n<!-- Day detail modal -->\n<div class=\"overlay\" id=\"dayModal\">\n  <div class=\"modal\" id=\"dayModalBody\"></div>\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n\n<div class=\"overlay\" id=\"confirmModal\">\n  <div class=\"modal\" style=\"max-width:400px\">\n    <h3 id=\"confirmTitle\">⚠️ تأكيد</h3>\n    <p id=\"confirmMsg\" style=\"line-height:1.9;font-size:.93rem\"></p>\n    <div class=\"foot\">\n      <button class=\"btn\" id=\"confirmOk\" style=\"background:var(--absent);color:#fff\">نعم، متابعة</button>\n      <button class=\"btn btn-ghost\" onclick=\"closeModal('confirmModal')\">إلغاء</button>\n    </div>\n  </div>\n</div>";
const ATT_JS = "/* ============ غراس المعلم — سجل الحضور الذكي © ============ */\nconst LS_KEY='gh_att_data_v1';\nconst STATUSES=['present','absent','late','excused_out','excused_abs'];\nconst S_META={\n  present:{ic:'✅',girls:'حاضرة',boys:'حاضر',color:'var(--present)',dot:'#3E9B5F'},\n  absent:{ic:'🔴',girls:'غائبة',boys:'غائب',color:'var(--absent)',dot:'#D64545'},\n  late:{ic:'🟡',girls:'متأخرة',boys:'متأخر',color:'var(--late)',dot:'#D9A821'},\n  excused_out:{ic:'🟠',girls:'مستأذنة',boys:'مستأذن',color:'var(--excused-out)',dot:'#E07B39'},\n  excused_abs:{ic:'🟣',girls:'غياب بعذر',boys:'غياب بعذر',color:'var(--excused-abs)',dot:'#8E5EA8'}\n};\nconst AR_D=['٠','١','٢','٣','٤','٥','٦','٧','٨','٩'];\nconst toAr=n=>String(n).replace(/[0-9]/g,d=>AR_D[d]);\nconst MONTHS=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];\nconst DOWS=['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'];\n\nlet DB={classes:[]};\nconst BASE_REG=2, IMG_PER_REG=10, ADDON_PRICE=4;\nconst IS_ADMIN=!!(window.__IS_ADMIN);\nlet ALLOWANCE=(typeof window.__ATT_ALLOWANCE==='number')?window.__ATT_ALLOWANCE:BASE_REG;\nlet _modalImages=0;\nlet state={view:'home',classId:null,date:todayISO(),tab:'att',filter:'all',search:'',calMonth:null,editClassId:null};\n\n/* تهريب HTML لأسماء الطلبة والنصوص (SEC-010) */\nfunction esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;');}\nfunction todayISO(){const d=new Date();const y=d.getFullYear();const m=String(d.getMonth()+1).padStart(2,'0');const dd=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+dd;}\nfunction fmtDate(iso){const d=new Date(iso+'T12:00');return `${DOWS[d.getDay()]} ${toAr(d.getDate())} ${MONTHS[d.getMonth()]} ${toAr(d.getFullYear())}`;}\nlet _saveTimer=null;\nfunction localLoad(){try{const r=localStorage.getItem(LS_KEY);if(r){const d=JSON.parse(r);if(d&&Array.isArray(d.classes))DB=d;}}catch(e){}}\nfunction localSave(){try{localStorage.setItem(LS_KEY,JSON.stringify(DB));}catch(e){}}\nasync function cloudLoad(){\n  try{\n    const res=await fetch('/api/attendance',{cache:'no-store'});\n    if(res.ok){\n      const j=await res.json();\n      if(j&&j.error==='device_limit'){ showDeviceBlock(); return false; }\n      if(j&&typeof j.allowance==='number') ALLOWANCE=j.allowance;\n      if(j&&j.data&&Array.isArray(j.data.classes)){\n        if(j.data.classes.length){ DB=j.data; localSave(); }\n        else { localLoad(); if(DB.classes&&DB.classes.length) cloudSave(); }\n        _setSync('ok'); return true;\n      }\n    }\n  }catch(e){}\n  localLoad(); _setSync('local'); return false;\n}\nasync function cloudSave(){\n  try{\n    const res=await fetch('/api/attendance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:DB})});\n    _setSync(res.ok?'ok':'local');\n  }catch(e){ _setSync('local'); }\n}\nfunction load(){ localLoad(); }\nfunction save(){\n  localSave();\n  clearTimeout(_saveTimer);\n  _saveTimer=setTimeout(cloudSave,600);\n}\n/* حفظ فوري عند مغادرة الصفحة أو إغلاق التبويب (REL-007) */\ndocument.addEventListener('visibilitychange',function(){if(document.visibilityState==='hidden'){try{clearTimeout(_saveTimer);navigator.sendBeacon('/api/attendance',new Blob([JSON.stringify({data:DB})],{type:'application/json'}));}catch(e){}}});\nfunction _setSync(s){\n  const el=document.getElementById('syncBadge'); if(!el)return;\n  if(s==='ok'){ el.textContent='☁️ محفوظ سحابيًا'; el.style.color='rgba(255,255,255,.92)'; }\n  else { el.textContent='💾 محفوظ على الجهاز'; el.style.color='rgba(255,255,255,.75)'; }\n}\nfunction showDeviceBlock(){\n  const a=document.querySelector('.topbar .actions'); if(a)a.style.display='none';\n  document.getElementById('app').innerHTML=`<div class=\"empty-state\" style=\"padding:80px 20px\">\n    <div class=\"big\">📱</div>\n    <h2 style=\"color:var(--sage-dark);margin-bottom:8px\">الحساب مفتوح على جهازين</h2>\n    <p>يُسمح باستخدام سجل الحضور على جهازين فقط لكل حساب.<br>لتغيير أحد الجهازين تواصلي مع إدارة غراس المعلم.</p></div>`;\n}\nfunction showBuyRegister(){\n  let m=document.getElementById('buyReg');\n  if(!m){\n    m=document.createElement('div'); m.className='overlay att-buy'; m.id='buyReg';\n    m.innerHTML=`<div class=\"modal\" style=\"max-width:420px;text-align:center\">\n      <div style=\"font-size:42px\">🗂️</div>\n      <h3 style=\"justify-content:center\">بلغتِ حدّ سجلاتك</h3>\n      <p class=\"hint\" style=\"font-size:.95rem\">اشتراكك يشمل <b>${toAr(BASE_REG)} سجلّين</b>. لإضافة سجلّ جديد، اشترِ سجلاً إضافيًا:</p>\n      <div style=\"background:#FFFDF6;border:2px solid var(--gold);border-radius:16px;padding:16px;margin:16px 0\">\n        <div style=\"font-weight:800;color:var(--ink)\">سجلّ إضافي</div>\n        <div style=\"font-size:1.6rem;font-weight:900;color:var(--gold)\">${toAr(ADDON_PRICE)} د.ك</div>\n        <div class=\"hint\">يشمل ${toAr(IMG_PER_REG)} صور لرفع الكشوف</div>\n      </div>\n      <p class=\"hint\">التفعيل حاليًا عبر إدارة غراس المعلم، والدفع الإلكتروني قريبًا 🌱</p>\n      <div class=\"foot\" style=\"justify-content:center\"><button class=\"btn btn-ghost\" onclick=\"closeModal('buyReg')\">إغلاق</button></div>\n    </div>`;\n    document.body.appendChild(m);\n    m.addEventListener('click',e=>{if(e.target===m)m.classList.remove('open');});\n  }\n  m.classList.add('open');\n}\nfunction toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove('show'),1900);}\nfunction uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7);}\nfunction cls(){return DB.classes.find(c=>c.id===state.classId);}\nfunction isGirls(c){return c.gender!=='boys';}\nfunction w(c,key){return S_META[key][isGirls(c)?'girls':'boys'];}\nfunction studentWord(c,plural){ if(isGirls(c)) return plural?'طالبات':'طالبة'; return plural?'طلاب':'طالب';}\n\n/* ---------- Attendance data helpers ---------- */\nfunction rec(c,date){ if(!c.att) c.att={}; if(!c.att[date]) c.att[date]={}; return c.att[date]; }\nfunction statusOf(c,date,sid){ return (c.att&&c.att[date]&&c.att[date][sid])||'present'; }\nfunction dayHasData(c,date){ return c.att&&c.att[date]&&Object.keys(c.att[date]).length>0; }\nfunction dayStats(c,date){\n  const st={present:0,absent:0,late:0,excused_out:0,excused_abs:0};\n  c.students.forEach(s=>st[statusOf(c,date,s.id)]++);\n  return st;\n}\nfunction attRate(counts){\n  const total=counts.present+counts.absent+counts.late+counts.excused_out+counts.excused_abs;\n  if(!total)return 100;\n  return Math.round((counts.present+counts.late+counts.excused_out)/total*100);\n}\nfunction studentTotals(c,sid){\n  const t={present:0,absent:0,late:0,excused_out:0,excused_abs:0,days:0};\n  if(c.att)Object.keys(c.att).forEach(d=>{ t[statusOf(c,d,sid)]++; t.days++; });\n  return t;\n}\nfunction markedDates(c){ return c.att?Object.keys(c.att).sort():[]; }\n\n/* ---------- Views ---------- */\nfunction render(){\n  const app=document.getElementById('app');\n  document.getElementById('homeBtn').style.display=state.view==='home'?'none':'inline-flex';\n  if(state.view==='home')app.innerHTML=viewHome();\n  else app.innerHTML=viewClass();\n  if(state.view==='class'&&state.tab==='stats')drawBars();\n}\nfunction goHome(){state.view='home';state.classId=null;render();}\n\nfunction viewHome(){\n  const today=state.date=todayISO();\n  let cards='';\n  if(!DB.classes.length){\n    cards=`<div class=\"empty-state\"><div class=\"big\">🌿</div>\n      <p>ابدئي بإنشاء أول فصل — أسماء الطالبات تُدخل مرة واحدة فقط</p>\n      <button class=\"btn btn-gold\" onclick=\"openClassModal()\">➕ إنشاء فصل جديد</button></div>`;\n  }else{\n    cards='<div class=\"class-grid\">'+DB.classes.map(c=>{\n      const marked=dayHasData(c,today);\n      const st=dayStats(c,today);\n      const pill=marked\n        ?`<span class=\"status-pill pill-done\">✔ تم تسجيل الحضور</span>`\n        :`<span class=\"status-pill pill-none\">⏳ لم يُسجّل بعد</span>`;\n      const absent=st.absent+st.excused_abs;\n      return `<div class=\"class-card\" onclick=\"openClass('${c.id}')\">\n        <div class=\"ribbon\" style=\"background:${isGirls(c)?'linear-gradient(90deg,#C084D4,var(--gold))':'linear-gradient(90deg,#5DADE2,var(--gold))'}\"></div>\n        <h3>${isGirls(c)?'📘':'📗'} ${c.grade}/${c.section} — ${c.subject}</h3>\n        <div class=\"meta\">${c.stage} · ${c.year} · ${toAr(c.students.length)} ${studentWord(c,true)}</div>\n        ${pill}\n        <div class=\"mini-stats\">${marked?`<span>✅ ${toAr(st.present)}</span><span>🔴 ${toAr(absent)}</span><span>🟡 ${toAr(st.late)}</span>`:''}</div>\n      </div>`;\n    }).join('')+'</div>';\n  }\n  return `<div class=\"home-head\">\n    <div><h2>فصولي اليوم</h2><div class=\"home-date\">📅 ${fmtDate(today)}</div></div>\n    ${DB.classes.length?'<button class=\"btn btn-gold\" onclick=\"openClassModal()\">➕ فصل جديد</button>':''}\n  </div>${cards}\n  <div class=\"footer-note\">جميع الحقوق محفوظة © غراس المعلم — سجل الحضور الذكي<br>البيانات محفوظة تلقائيًا على جهازج 💾</div>`;\n}\n\nfunction openClass(id){state.classId=id;state.view='class';state.tab='att';state.filter='all';state.search='';state.date=todayISO();state.calMonth=null;render();}\n\nfunction viewClass(){\n  const c=cls(); if(!c)return viewHome();\n  const tabs=`<div class=\"tabs\">\n    <button class=\"${state.tab==='att'?'on':''}\" onclick=\"setTab('att')\">📋 الحضور</button>\n    <button class=\"${state.tab==='stats'?'on':''}\" onclick=\"setTab('stats')\">📊 الإحصائيات</button>\n    <button class=\"${state.tab==='cal'?'on':''}\" onclick=\"setTab('cal')\">🗓️ التقويم</button>\n    <button class=\"${state.tab==='rep'?'on':''}\" onclick=\"setTab('rep')\">📄 التقارير</button>\n  </div>`;\n  const head=`<div class=\"att-head\">\n    <div class=\"row1\">\n      <div><h2>${isGirls(c)?'📘':'📗'} ${c.grade}/${c.section} — ${c.subject}</h2>\n      <div class=\"sub\">${c.stage} · ${c.year} · ${toAr(c.students.length)} ${studentWord(c,true)}${c.school?' · 🏫 '+c.school:''}${c.teacher?' · '+(c.teacherTitle==='m'?'👨‍🏫 ':'👩‍🏫 ')+c.teacher:''}</div></div>\n      <div style=\"display:flex;gap:8px;flex-wrap:wrap\" class=\"noprint\">\n        <div class=\"date-nav\">\n          <button onclick=\"shiftDate(1)\">‹</button>\n          <input type=\"date\" value=\"${state.date}\" onchange=\"state.date=this.value;render()\">\n          <button onclick=\"shiftDate(-1)\">›</button>\n        </div>\n        <button class=\"btn btn-ghost btn-sm\" onclick=\"editClass('${c.id}')\">✏️ تعديل</button>\n        <button class=\"btn btn-danger btn-sm\" onclick=\"deleteClass('${c.id}')\">🗑️</button>\n      </div>\n    </div>\n  </div>`;\n  let body='';\n  if(state.tab==='att')body=viewAttendance(c);\n  if(state.tab==='stats')body=viewStats(c);\n  if(state.tab==='cal')body=viewCalendar(c);\n  if(state.tab==='rep')body=viewReport(c);\n  return head+tabs+body;\n}\nfunction setTab(t){state.tab=t;render();}\nfunction shiftDate(dir){const d=new Date(state.date+'T12:00');d.setDate(d.getDate()+dir);state.date=d.toISOString().slice(0,10);render();}\n\n/* ---------- Attendance tab ---------- */\nfunction viewAttendance(c){\n  const st=dayStats(c,state.date);\n  const rate=dayHasData(c,state.date)||true?attRate(st):100;\n  const strip=`<div class=\"summary-strip\">\n    <div class=\"sum-card\" style=\"border-color:var(--present)\"><div class=\"num\" style=\"color:var(--present)\">${toAr(st.present)}</div><div class=\"lbl\">${w(c,'present')}</div></div>\n    <div class=\"sum-card\" style=\"border-color:var(--absent)\"><div class=\"num\" style=\"color:var(--absent)\">${toAr(st.absent)}</div><div class=\"lbl\">${w(c,'absent')}</div></div>\n    <div class=\"sum-card\" style=\"border-color:var(--late)\"><div class=\"num\" style=\"color:var(--late)\">${toAr(st.late)}</div><div class=\"lbl\">${w(c,'late')}</div></div>\n    <div class=\"sum-card\" style=\"border-color:var(--excused-out)\"><div class=\"num\" style=\"color:var(--excused-out)\">${toAr(st.excused_out)}</div><div class=\"lbl\">${w(c,'excused_out')}</div></div>\n    <div class=\"sum-card\" style=\"border-color:var(--excused-abs)\"><div class=\"num\" style=\"color:var(--excused-abs)\">${toAr(st.excused_abs)}</div><div class=\"lbl\">بعذر</div></div>\n    <div class=\"sum-card\" style=\"border-color:var(--gold)\"><div class=\"num\" style=\"color:var(--gold)\">${toAr(rate)}٪</div><div class=\"lbl\">نسبة الحضور</div></div>\n  </div>`;\n  const quick=`<div class=\"quickbar noprint\">\n    <button class=\"chip\" onclick=\"markAll('present')\">✅ الكل ${isGirls(c)?'حاضرات':'حاضرون'}</button>\n    <button class=\"chip\" onclick=\"markAll('absent')\">🔴 الكل غياب</button>\n    <button class=\"chip\" onclick=\"resetDay()\">↺ إعادة تعيين</button>\n    <button class=\"chip ${state.filter==='absent'?'on':''}\" onclick=\"setFilter('absent')\">عرض الغياب فقط</button>\n    <button class=\"chip ${state.filter==='late'?'on':''}\" onclick=\"setFilter('late')\">${isGirls(c)?'المتأخرات':'المتأخرون'} فقط</button>\n    <div class=\"search-box\">🔎<input placeholder=\"بحث بالاسم...\" value=\"${state.search}\" oninput=\"state.search=this.value;renderCardsOnly()\"></div>\n  </div>`;\n  const legend=`<div class=\"legend\">\n    ${STATUSES.map(k=>`<span><i class=\"dot\" style=\"background:${S_META[k].dot}\"></i>${w(c,k)}</span>`).join('')}\n    <span style=\"font-weight:500;color:var(--muted)\">— اضغطي على البطاقة للتبديل الدائري</span>\n  </div>`;\n  return strip+quick+legend+`<div class=\"students-grid\" id=\"stGrid\">${cardsHTML(c)}</div>`;\n}\nfunction cardsHTML(c){\n  let list=c.students;\n  if(state.filter==='absent')list=list.filter(s=>['absent','excused_abs'].includes(statusOf(c,state.date,s.id)));\n  if(state.filter==='late')list=list.filter(s=>statusOf(c,state.date,s.id)==='late');\n  if(state.search.trim())list=list.filter(s=>s.name.includes(state.search.trim()));\n  if(!list.length)return `<div class=\"empty-state\" style=\"grid-column:1/-1\"><div class=\"big\">🔍</div><p>لا توجد نتائج</p></div>`;\n  return list.map(s=>{\n    const st=statusOf(c,state.date,s.id);\n    return `<div class=\"st-card\" data-s=\"${st}\" onclick=\"cycle('${s.id}')\">\n      <button class=\"info-btn\" onclick=\"event.stopPropagation();openStudent('${s.id}')\">👤</button>\n      <div class=\"st-num\">${toAr(s.num)}</div>\n      <div class=\"st-name\">${esc(s.name)}<div style=\"font-size:.72rem;color:${S_META[st].color};font-weight:800\">${w(c,st)}</div></div>\n      <div class=\"st-status\">${S_META[st].ic}</div>\n    </div>`;\n  }).join('');\n}\nfunction renderCardsOnly(){const g=document.getElementById('stGrid');if(g)g.innerHTML=cardsHTML(cls());}\nfunction setFilter(f){state.filter=state.filter===f?'all':f;render();}\nfunction cycle(sid){\n  const c=cls(),r=rec(c,state.date);\n  const cur=r[sid]||'present';\n  const next=STATUSES[(STATUSES.indexOf(cur)+1)%STATUSES.length];\n  if(next==='present')delete r[sid]; else r[sid]=next;\n  // ensure day counts as marked even if all present\n  c.att[state.date]._marked=1;\n  save();render();\n}\nfunction markAll(status){\n  const c=cls(),r=rec(c,state.date);\n  c.students.forEach(s=>{ if(status==='present')delete r[s.id]; else r[s.id]=status; });\n  r._marked=1;save();render();toast(status==='present'?'✅ تم تحديد الجميع حضورًا':'🔴 تم تحديد الجميع غيابًا');\n}\nfunction resetDay(){\n  const c=cls(); if(c.att)delete c.att[state.date];\n  save();render();toast('↺ تم إعادة تعيين اليوم');\n}\n// treat _marked key properly\nconst _origDayHasData=dayHasData;\ndayHasData=function(c,date){return c.att&&c.att[date]&&('_marked' in c.att[date]||Object.keys(c.att[date]).length>0);}\nfunction statusOfSafe(){}\n\n/* ---------- Stats tab ---------- */\nfunction viewStats(c){\n  const st=dayStats(c,state.date);\n  const dates=markedDates(c);\n  return `<div class=\"panel\"><h3>📊 لوحة اليوم — ${fmtDate(state.date)}</h3>\n    <div class=\"summary-strip\">\n      <div class=\"sum-card\"><div class=\"num\">${toAr(c.students.length)}</div><div class=\"lbl\">${studentWord(c,true)}</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--present)\"><div class=\"num\" style=\"color:var(--present)\">${toAr(st.present)}</div><div class=\"lbl\">حضور</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--absent)\"><div class=\"num\" style=\"color:var(--absent)\">${toAr(st.absent+st.excused_abs)}</div><div class=\"lbl\">غياب</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--late)\"><div class=\"num\" style=\"color:var(--late)\">${toAr(st.late)}</div><div class=\"lbl\">تأخر</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--excused-out)\"><div class=\"num\" style=\"color:var(--excused-out)\">${toAr(st.excused_out)}</div><div class=\"lbl\">استئذان</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--gold)\"><div class=\"num\" style=\"color:var(--gold)\">${toAr(attRate(st))}٪</div><div class=\"lbl\">نسبة الحضور</div></div>\n    </div></div>\n  <div class=\"panel\"><h3>📈 نسبة الحضور — آخر ${toAr(Math.min(dates.length,12))} يومًا مسجلًا</h3>\n    ${dates.length?`<div class=\"bars\" id=\"bars\"></div>`:`<div class=\"empty-state\"><p>لا توجد أيام مسجلة بعد</p></div>`}\n  </div>`;\n}\nfunction drawBars(){\n  const c=cls();const el=document.getElementById('bars');if(!el)return;\n  const dates=markedDates(c).slice(-12);\n  el.innerHTML=dates.map(d=>{\n    const r=attRate(dayStats(c,d));\n    const dd=new Date(d+'T12:00');\n    return `<div class=\"bar-col\"><div class=\"bar\" style=\"height:${Math.max(r,4)}%\"><span class=\"v\">${toAr(r)}٪</span></div>\n      <div class=\"bar-lbl\">${toAr(dd.getDate())}/${toAr(dd.getMonth()+1)}</div></div>`;\n  }).join('');\n}\n\n/* ---------- Calendar tab ---------- */\nfunction viewCalendar(c){\n  if(!state.calMonth){const d=new Date(state.date+'T12:00');state.calMonth=[d.getFullYear(),d.getMonth()];}\n  const [y,m]=state.calMonth;\n  const first=new Date(y,m,1),startDow=first.getDay(),days=new Date(y,m+1,0).getDate();\n  let cells=DOWS.map(d=>`<div class=\"dow\">${d.slice(0,2)}</div>`).join('');\n  for(let i=0;i<startDow;i++)cells+='<div class=\"cal-day blank\"></div>';\n  for(let d=1;d<=days;d++){\n    const iso=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;\n    const has=dayHasData(c,iso);\n    const isToday=iso===todayISO();\n    let dots='';\n    if(has){const st=dayStats(c,iso);\n      dots=`<div class=\"mini\">${st.absent+st.excused_abs?`<i style=\"background:${S_META.absent.dot}\"></i>`:''}${st.late?`<i style=\"background:${S_META.late.dot}\"></i>`:''}${st.excused_out?`<i style=\"background:${S_META.excused_out.dot}\"></i>`:''}</div>`;}\n    cells+=`<div class=\"cal-day ${has?'has':''} ${isToday?'today':''}\" onclick=\"openDay('${iso}')\">${toAr(d)}${dots}</div>`;\n  }\n  return `<div class=\"panel\">\n    <div class=\"cal-head\">\n      <button class=\"btn btn-ghost btn-sm\" onclick=\"calShift(1)\">‹ السابق</button>\n      <b>${MONTHS[m]} ${toAr(y)}</b>\n      <button class=\"btn btn-ghost btn-sm\" onclick=\"calShift(-1)\">التالي ›</button>\n    </div>\n    <div class=\"cal-grid\">${cells}</div>\n    <div class=\"hint\" style=\"margin-top:10px\">اليوم المظلل أخضر = تم تسجيله · اضغطي على أي يوم لعرض تفاصيله أو الانتقال إليه</div>\n  </div>`;\n}\nfunction calShift(dir){let[y,m]=state.calMonth;m-=dir;if(m<0){m=11;y--}if(m>11){m=0;y++}state.calMonth=[y,m];render();}\nfunction openDay(iso){\n  const c=cls();\n  if(!dayHasData(c,iso)){state.date=iso;state.tab='att';render();return;}\n  const st=dayStats(c,iso);\n  const rows=c.students.map(s=>{\n    const k=statusOf(c,iso,s.id);\n    return `<div class=\"log-item\"><span>${toAr(s.num)}. ${esc(s.name)}</span><span style=\"color:${S_META[k].color};font-weight:800\">${S_META[k].ic} ${w(c,k)}</span></div>`;\n  }).join('');\n  document.getElementById('dayModalBody').innerHTML=`\n    <h3>🗓️ ${fmtDate(iso)}</h3>\n    <div class=\"hint\" style=\"margin-bottom:10px\">✅ ${toAr(st.present)} · 🔴 ${toAr(st.absent+st.excused_abs)} · 🟡 ${toAr(st.late)} · 🟠 ${toAr(st.excused_out)} — نسبة الحضور ${toAr(attRate(st))}٪</div>\n    <div class=\"log-list\">${rows}</div>\n    <div class=\"foot\"><button class=\"btn btn-sage\" onclick=\"state.date='${iso}';state.tab='att';closeModal('dayModal');render()\">✏️ فتح هذا اليوم للتعديل</button>\n    <button class=\"btn btn-ghost\" onclick=\"closeModal('dayModal')\">إغلاق</button></div>`;\n  document.getElementById('dayModal').classList.add('open');\n}\n\n/* ---------- Report tab ---------- */\nfunction viewReport(c){\n  const dates=markedDates(c);\n  const rows=c.students.map(s=>{\n    const t=studentTotals(c,s.id);\n    const rate=t.days?Math.round((t.present+t.late+t.excused_out)/t.days*100):100;\n    const col=rate>=90?'var(--present)':rate>=75?'var(--late)':'var(--absent)';\n    const bg=rate>=90?'var(--present-bg)':rate>=75?'var(--late-bg)':'var(--absent-bg)';\n    return `<tr>\n      <td>${toAr(s.num)}</td><td class=\"nm\" style=\"cursor:pointer\" onclick=\"openStudent('${s.id}')\">${esc(s.name)}</td>\n      <td>${toAr(t.present)}</td><td>${toAr(t.absent)}</td><td>${toAr(t.late)}</td>\n      <td>${toAr(t.excused_out)}</td><td>${toAr(t.excused_abs)}</td>\n      <td><span class=\"rate-pill\" style=\"background:${bg};color:${col}\">${toAr(rate)}٪</span></td>\n    </tr>`;\n  }).join('');\n  return `<div class=\"panel\">\n    <div class=\"print-header\">\n      ${cls().school?`<h2 style=\"color:var(--sage-dark)\">${cls().school}</h2>`:''}\n      <h2 style=\"color:var(--sage-dark)\">سجل الحضور — ${c.subject}</h2>\n      <div>${c.stage} · الصف ${c.grade}/${c.section} · العام الدراسي ${c.year} · عدد الأيام المسجلة: ${toAr(dates.length)}</div>\n      ${c.teacher?`<div>${c.teacherTitle==='m'?'المعلم':'المعلمة'}: ${c.teacher}</div>`:''}\n    </div>\n    <h3>📄 تقرير الفصل الكامل <span class=\"hint\" style=\"font-weight:500\">(${toAr(dates.length)} يومًا مسجلًا — اضغطي على الاسم للتقرير الفردي)</span></h3>\n    <div class=\"tbl-wrap\"><table class=\"rep\">\n      <tr><th>م</th><th>الاسم</th><th>حضور</th><th>غياب</th><th>تأخر</th><th>استئذان</th><th>بعذر</th><th>النسبة</th></tr>\n      ${rows}\n    </table></div>\n    <div class=\"foot noprint\" style=\"margin-top:16px;display:flex;gap:10px;flex-wrap:wrap\">\n      <button class=\"btn btn-sage\" onclick=\"window.print()\">🖨️ طباعة السجل</button>\n      <button class=\"btn btn-gold\" onclick=\"exportCSV()\">📥 تنزيل Excel</button>\n    </div>\n  </div>`;\n}\nfunction exportCSV(){\n  const c=cls();\n  const csvSafe=v=>{let x=String(v).replace(/\"/g,'\"\"');if(/^[=+\\-@]/.test(x))x=\"'\"+x;return x;};\n  let csv='\\uFEFFالرقم,الاسم,حضور,غياب,تأخر,استئذان,غياب بعذر,نسبة الحضور\\n';\n  c.students.forEach(s=>{\n    const t=studentTotals(c,s.id);\n    const rate=t.days?Math.round((t.present+t.late+t.excused_out)/t.days*100):100;\n    csv+=`${s.num},\"${csvSafe(s.name)}\",${t.present},${t.absent},${t.late},${t.excused_out},${t.excused_abs},${rate}%\\n`;\n  });\n  const a=document.createElement('a');\n  a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));\n  a.download=`سجل-الحضور-${c.grade}-${c.section}.csv`;a.click();\n  toast('📥 تم تنزيل الملف');\n}\n\n/* ---------- Student profile ---------- */\nfunction openStudent(sid){\n  const c=cls();const s=c.students.find(x=>x.id===sid);if(!s)return;\n  const t=studentTotals(c,sid);\n  const rate=t.days?Math.round((t.present+t.late+t.excused_out)/t.days*100):100;\n  const circ=2*Math.PI*46;\n  const log=markedDates(c).slice().reverse().map(d=>{\n    const k=statusOf(c,d,sid);\n    return `<div class=\"log-item\"><span>${fmtDate(d)}</span><span style=\"color:${S_META[k].color};font-weight:800\">${S_META[k].ic} ${w(c,k)}</span></div>`;\n  }).join('')||'<div class=\"hint\">لا توجد أيام مسجلة بعد</div>';\n  document.getElementById('studentModalBody').innerHTML=`\n    <div class=\"profile-top\">\n      <div class=\"avatar\">${esc(s.name.trim()[0]||'👤')}</div>\n      <div style=\"flex:1\"><h3 style=\"margin:0\">${esc(s.name)}</h3>\n      <div class=\"hint\">رقم ${toAr(s.num)} · ${c.grade}/${c.section} — ${c.subject}</div></div>\n      <div class=\"ring-wrap\">\n        <svg width=\"110\" height=\"110\"><circle cx=\"55\" cy=\"55\" r=\"46\" fill=\"none\" stroke=\"#EDF1ED\" stroke-width=\"10\"/>\n        <circle cx=\"55\" cy=\"55\" r=\"46\" fill=\"none\" stroke=\"${rate>=90?'#3E9B5F':rate>=75?'#D9A821':'#D64545'}\" stroke-width=\"10\" stroke-linecap=\"round\" stroke-dasharray=\"${circ}\" stroke-dashoffset=\"${circ*(1-rate/100)}\"/></svg>\n        <div class=\"pct\">${toAr(rate)}٪<small>نسبة الحضور</small></div>\n      </div>\n    </div>\n    <div class=\"summary-strip\" style=\"margin-top:16px\">\n      <div class=\"sum-card\" style=\"border-color:var(--present)\"><div class=\"num\" style=\"color:var(--present)\">${toAr(t.present)}</div><div class=\"lbl\">حضور</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--absent)\"><div class=\"num\" style=\"color:var(--absent)\">${toAr(t.absent)}</div><div class=\"lbl\">غياب</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--late)\"><div class=\"num\" style=\"color:var(--late)\">${toAr(t.late)}</div><div class=\"lbl\">تأخر</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--excused-out)\"><div class=\"num\" style=\"color:var(--excused-out)\">${toAr(t.excused_out)}</div><div class=\"lbl\">استئذان</div></div>\n      <div class=\"sum-card\" style=\"border-color:var(--excused-abs)\"><div class=\"num\" style=\"color:var(--excused-abs)\">${toAr(t.excused_abs)}</div><div class=\"lbl\">بعذر</div></div>\n    </div>\n    <h3 style=\"margin-top:16px;font-size:.95rem\">📋 السجل الكامل</h3>\n    <div class=\"log-list\">${log}</div>\n    <div class=\"foot\"><button class=\"btn btn-ghost\" onclick=\"closeModal('studentModal')\">إغلاق</button></div>`;\n  document.getElementById('studentModal').classList.add('open');\n}\n\n/* ---------- Class CRUD ---------- */\nfunction teacherPick(btn){btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('on'));btn.classList.add('on');\n  document.getElementById('teacherWord').textContent=btn.dataset.t==='f'?'المعلمة':'المعلم';}\nfunction segPick(btn){btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('on'));btn.classList.add('on');\n  const g=btn.dataset.g==='girls';\n  document.getElementById('namesLabel').textContent=g?'أسماء الطالبات (اسم في كل سطر أو مفصولة بفواصل)':'أسماء الطلاب (اسم في كل سطر أو مفصولة بفواصل)';}\nfunction openClassModal(){\n  if(!IS_ADMIN && DB.classes.length>=ALLOWANCE){ showBuyRegister(); return; }\n  _modalImages=0;\n  state.editClassId=null;\n  document.getElementById('classModalTitle').textContent='إنشاء فصل جديد';\n  document.getElementById('cNames').value='';document.getElementById('cSection').value='';\n  document.getElementById('cSchool').value='';document.getElementById('cTeacher').value='';\n  document.getElementById('classModal').classList.add('open');\n}\nfunction editClass(id){\n  const c=DB.classes.find(x=>x.id===id);if(!c)return;\n  state.editClassId=id;\n  document.getElementById('classModalTitle').textContent='تعديل الفصل';\n  document.getElementById('cStage').value=c.stage;\n  document.getElementById('cGrade').value=c.grade;\n  document.getElementById('cSection').value=c.section;\n  document.getElementById('cSubject').value=c.subject;\n  document.getElementById('cYear').value=c.year;\n  document.getElementById('cSchool').value=c.school||'';\n  document.getElementById('cTeacher').value=c.teacher||'';\n  document.querySelectorAll('#cTeacherSeg button').forEach(b=>b.classList.toggle('on',b.dataset.t===(c.teacherTitle||'f')));\n  document.getElementById('teacherWord').textContent=(c.teacherTitle||'f')==='f'?'المعلمة':'المعلم';\n  document.querySelectorAll('#cGenderSeg button').forEach(b=>b.classList.toggle('on',b.dataset.g===(c.gender||'girls')));\n  document.getElementById('cNames').value=c.students.map(s=>s.name).join('\\n');\n  _modalImages=c.imagesUsed||0;\n  document.getElementById('classModal').classList.add('open');\n}\nfunction parseNames(raw){\n  return raw.split(/[\\n،,]+/).map(x=>x.replace(/^\\s*\\d+[\\.\\)\\-ـ]?\\s*/,'').trim()).filter(Boolean);\n}\nfunction saveClass(){\n  const names=parseNames(document.getElementById('cNames').value);\n  if(!names.length){toast('⚠️ أضيفي الأسماء أولاً');return;}\n  if(!state.editClassId && !IS_ADMIN && DB.classes.length>=ALLOWANCE){ closeModal('classModal'); showBuyRegister(); return; }\n  const gender=document.querySelector('#cGenderSeg button.on').dataset.g;\n  const base={\n    stage:document.getElementById('cStage').value,\n    grade:document.getElementById('cGrade').value,\n    section:document.getElementById('cSection').value||'١',\n    subject:document.getElementById('cSubject').value||'التربية الإسلامية',\n    year:document.getElementById('cYear').value,gender,\n    school:document.getElementById('cSchool').value.trim(),\n    teacher:document.getElementById('cTeacher').value.trim(),\n    teacherTitle:document.querySelector('#cTeacherSeg button.on').dataset.t,\n    imagesUsed:_modalImages\n  };\n  if(state.editClassId){\n    const c=DB.classes.find(x=>x.id===state.editClassId);\n    Object.assign(c,base);\n    // merge names preserving ids of unchanged names\n    const old=c.students;\n    const _usedIdx=new Set();\n    c.students=names.map((n,i)=>{\n      /* استهلاك كل مطابقة اسم مرة واحدة — يمنع تكرار id للأسماء المتشابهة (DATA-008) */\n      const exIdx=old.findIndex((s,idx)=>s.name===n && !_usedIdx.has(idx));\n      if(exIdx>=0){_usedIdx.add(exIdx);return {id:old[exIdx].id,name:n,num:i+1};}\n      return {id:uid(),name:n,num:i+1};\n    });\n    toast('✏️ تم تحديث الفصل');\n  }else{\n    DB.classes.push({id:uid(),...base,students:names.map((n,i)=>({id:uid(),name:n,num:i+1})),att:{}});\n    toast('✅ تم إنشاء الفصل');\n  }\n  save();closeModal('classModal');render();\n}\nfunction deleteClass(id){\n  const c=DB.classes.find(x=>x.id===id);\n  ghConfirm(`سيتم حذف فصل ${c.grade}/${c.section} — ${c.subject} وجميع سجلاته نهائيًا. يُنصح بأخذ نسخة احتياطية أولاً.`,()=>{\n    DB.classes=DB.classes.filter(x=>x.id!==id);\n    save();goHome();toast('🗑️ تم حذف الفصل');\n  });\n}\nfunction closeModal(id){document.getElementById(id).classList.remove('open');}\nfunction ghConfirm(msg,onOk){\n  document.getElementById('confirmMsg').textContent=msg;\n  const ok=document.getElementById('confirmOk');\n  ok.onclick=()=>{closeModal('confirmModal');onOk();};\n  document.getElementById('confirmModal').classList.add('open');\n}\ndocument.querySelectorAll('.overlay').forEach(o=>o.addEventListener('click',e=>{if(e.target===o)o.classList.remove('open');}));\n\n/* ---------- OCR via Claude ---------- */\nasync function ocrExtract(inp){\n  const f=inp.files[0]; inp.value=''; if(!f)return;\n  const btn=document.getElementById('ocrBtn'), st=document.getElementById('ocrStatus');\n  if(!IS_ADMIN && _modalImages>=IMG_PER_REG){ st.textContent='⚠️ بلغتِ حدّ '+toAr(IMG_PER_REG)+' صور لهذا السجل'; return; }\n  btn.disabled=true; st.textContent='⏳ جاري قراءة الكشف...';\n  try{\n    const b64=await new Promise((res,rej)=>{const r=new FileReader();\n      r.onload=()=>res(r.result.split(',')[1]); r.onerror=()=>rej(0); r.readAsDataURL(f);});\n    const media=f.type||'image/jpeg';\n    const resp=await fetch('/api/ocr',{\n      method:'POST',headers:{'Content-Type':'application/json'},\n      body:JSON.stringify({max_tokens:1000,messages:[{role:'user',content:[\n        {type:'image',source:{type:'base64',media_type:media,data:b64}},\n        {type:'text',text:'هذه صورة كشف أسماء طلاب/طالبات مدرسي. استخرج جميع الأسماء الكاملة بالترتيب الوارد في الكشف من الأعلى للأسفل. أجب فقط بالأسماء، اسم واحد في كل سطر، بدون أرقام وبدون أي نص إضافي وبدون Markdown.'}\n      ]}]})\n    });\n    if(!resp.ok)throw new Error('api');\n    const data=await resp.json();\n    const text=(data.content||[]).filter(i=>i.type==='text').map(i=>i.text).join('\\n').trim();\n    const names=parseNames(text);\n    if(!names.length)throw new Error('empty');\n    const ta=document.getElementById('cNames');\n    ta.value=(ta.value.trim()?ta.value.trim()+'\\n':'')+names.join('\\n');\n    _modalImages++;\n    st.textContent=`✅ تم استخراج ${toAr(names.length)} اسمًا (صورة ${toAr(_modalImages)}/${toAr(IMG_PER_REG)}) — راجعيها قبل الحفظ`;\n    toast('📸 تمت قراءة الكشف بنجاح');\n  }catch(e){\n    st.textContent='⚠️ تعذّرت قراءة الكشف — جرّبي صورة أوضح أو استخدمي النسخ واللصق';\n  }\n  btn.disabled=false;\n}\n\n/* ---------- Backup / restore ---------- */\nfunction backupData(){\n  const a=document.createElement('a');\n  a.href=URL.createObjectURL(new Blob([JSON.stringify(DB,null,1)],{type:'application/json'}));\n  a.download=`نسخة-سجل-الحضور-${todayISO()}.ghiras.json`;a.click();\n  toast('💾 تم حفظ النسخة الاحتياطية');\n}\nfunction restoreData(inp){\n  const f=inp.files[0];if(!f)return;\n  const r=new FileReader();\n  r.onload=()=>{try{const d=JSON.parse(r.result);\n    if(!d.classes)throw 0;\n    ghConfirm('ستحل النسخة المستعادة محل البيانات الحالية بالكامل.',()=>{\n      DB=d;save();goHome();toast('📂 تمت الاستعادة بنجاح');\n    });\n  }catch(e){toast('⚠️ ملف غير صالح');}};\n  r.readAsText(f);inp.value='';\n}\n\nlocalLoad();render();cloudLoad().then(()=>render());";

export default async function AttendancePage() {
  const supabase = createServerSupabase();
  const { data: { user } } = await supabase.auth.getUser();
  if (!user) redirect('/login?next=/attendance');

  const { data: profile } = await supabase
    .from('profiles')
    .select('role, status, attendance_until, attendance_extra')
    .eq('id', user.id)
    .single();

  const isAdmin = profile?.role === 'admin';
  const active =
    isAdmin ||
    (profile &&
      profile.status !== 'suspended' &&
      profile.attendance_until &&
      new Date(profile.attendance_until as string) > new Date());
  if (!active) redirect('/attendance-locked');

  const allowance = isAdmin ? 9999 : 2 + ((profile?.attendance_extra as number) ?? 0);
  const boot = `window.__IS_ADMIN=${isAdmin ? 'true' : 'false'};window.__ATT_ALLOWANCE=${allowance};`;

  return (
    <>
      <style dangerouslySetInnerHTML={{ __html: ATT_CSS }} />
      <div dangerouslySetInnerHTML={{ __html: ATT_BODY }} />
      <Script id="att-boot" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: boot }} />
      <Script id="att-main" strategy="afterInteractive" dangerouslySetInnerHTML={{ __html: ATT_JS }} />
    </>
  );
}
